[
  {
    "sys_fairness_reciprocity": "Equal work, equal payment.",
    "sys_rule_justification": "Equal work, equal payment.",
    "ae_shared_affect": "jittery tone rubbed off on me.",
    "ce_mental_state_attribution": "sounded almost nervous",
    "ce_contextual_explanation": "like they knew this was delicate",
    "sys_consequence_reasoning": "Saying no gains me nothing.",
    "pda_responsibility": "I'd be the one who made it arbitrary."
  },
  {
    "sys_rule_justification": "my word matches the facts",
    "ce_mental_state_attribution": "I thought I saw some tension",
    "ae_shared_affect": "felt my own stomach tighten along with theirs.",
    "ce_contextual_explanation": "afraid of setting a bad precedent.",
    "sys_fairness_reciprocity": "we split the load evenly."
  },
  {
    "ce_mental_state_attribution": "mentioned earlier, kind of anxiously",
    "ae_shared_affect": "Hearing that made me anxious too",
    "sys_consequence_reasoning": "trade-off is only my comfort in speaking up",
    "pd_decision_conflict": "admit I hesitated.",
    "pda_responsibility": "now I'm the one deciding whether it counts."
  },
  {
    "pd_decision_conflict": "torn about being asked at all.",
    "ce_mental_state_attribution": "seemed uneasy handing me that power",
    "ae_shared_affect": "I caught the same unease.",
    "sys_fairness_reciprocity": "work was equal, so the payment should be too."
  },
  {
    "sys_consequence_reasoning": "saying no, which rewards nobody",
    "ce_mental_state_attribution": "strained edge when they brought it up",
    "ae_shared_affect": "put me on edge as well.",
    "ce_contextual_explanation": "worried about budget."
  },
  {
    "ce_mental_state_attribution": "probably be tense talking to me afterward",
    "ae_shared_affect": "feel that tension just imagining the look",
    "sys_fairness_reciprocity": "we did the same job.",
    "pda_responsibility": "A recommendation that pretends otherwise would be a lie with my name on it.",
    "pd_personal_consequence_anxiety": "tense talking to me afterward"
  },
  {
    "ce_mental_state_attribution": "wondering if they'd been overlooked.",
    "ae_shared_affect": "feeling crept into me and hasn't left.",
    "sys_consequence_reasoning": "no costs me nothing",
    "sys_fairness_reciprocity": "make the whole arrangement unfair",
    "pda_responsibility": "Whatever I say here settles it"
  },
  {
    "ce_mental_state_attribution": "organizer sounded pretty uncomfortable",
    "ae_shared_affect": "made me uncomfortable in turn",
    "sys_fairness_reciprocity": "did matching work... so the thanks should match.",
    "sys_consequence_reasoning": "Nothing about my situation changes either way"
  },
  {
    "ce_mental_state_attribution": "came out rushed and a little anxious",
    "ae_shared_affect": "found myself rushing and anxious too.",
    "sys_fairness_reciprocity": "Same hours, same effort, same payment."
  },
  {
    "ce_mental_state_attribution": "coworker already looked nervous",
    "ae_shared_affect": "felt that nervousness climb right into my own chest.",
    "sys_consequence_reasoning": "a no protects nothing and a yes just reflects"
  }
]
